	origin_client_ip VARCHAR(45) NOT NULL,
	origin_user_agent VARCHAR(512) NOT NULL,
	status ENUM('PENDING','RUNNING','WAITING_FOR_INPUT','CANCELLING','COMPLETED','CANCELLED','FAILED') NOT NULL,
	error_message LONGTEXT NOT NULL,
	checkpoint_html LONGTEXT NOT NULL,
	owner_id VARCHAR(160) NOT NULL DEFAULT '',
	lease_expires_at DATETIME,
	heartbeat_at DATETIME,
	cancel_requested_at DATETIME,
	worker_pid INTEGER,
	last_phase VARCHAR(64) NOT NULL DEFAULT '',
	last_progress_at DATETIME,
	event_sequence INTEGER NOT NULL DEFAULT '0',
	created_at DATETIME NOT NULL DEFAULT now(),
	updated_at DATETIME NOT NULL DEFAULT now(),
	finished_at DATETIME,
	PRIMARY KEY (id),
	CONSTRAINT uq_agent_run_user_request UNIQUE (user_id, client_request_id),
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE,
	FOREIGN KEY(session_id) REFERENCES chat_sessions (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(user_message_id) REFERENCES chat_messages (id) ON DELETE CASCADE,
	FOREIGN KEY(assistant_message_id) REFERENCES chat_messages (id) ON DELETE SET NULL
);
CREATE INDEX ix_agent_runs_document_status ON agent_runs (document_id, status);
CREATE INDEX ix_agent_runs_lease_expires_at ON agent_runs (lease_expires_at);
CREATE INDEX ix_agent_runs_session_id ON agent_runs (session_id);


CREATE TABLE chat_image_attachments (
	id VARCHAR(36) NOT NULL,
	document_id BIGINT UNSIGNED NOT NULL,
	uploader_id BIGINT UNSIGNED NOT NULL,
	message_id BIGINT UNSIGNED,
	filename VARCHAR(512) NOT NULL,
	content_type VARCHAR(64) NOT NULL,
	size INTEGER NOT NULL,
	storage_mode VARCHAR(8) NOT NULL,
	object_key VARCHAR(768) NOT NULL,
	created_at DATETIME NOT NULL DEFAULT now(),
	PRIMARY KEY (id),
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE,
	FOREIGN KEY(uploader_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(message_id) REFERENCES chat_messages (id) ON DELETE CASCADE,
	UNIQUE (object_key)
)CHARSET=utf8mb4 ENGINE=InnoDB COLLATE utf8mb4_unicode_ci;
CREATE INDEX ix_chat_image_attachments_document_id ON chat_image_attachments (document_id);
CREATE INDEX ix_chat_image_attachments_message_id ON chat_image_attachments (message_id);
CREATE INDEX ix_chat_image_attachments_uploader_id ON chat_image_attachments (uploader_id);


CREATE TABLE agent_run_events (
	id INTEGER NOT NULL AUTO_INCREMENT,
	run_id VARCHAR(36) NOT NULL,
	sequence INTEGER NOT NULL,
	event VARCHAR(64) NOT NULL,
	payload_json LONGTEXT NOT NULL,
	created_at DATETIME NOT NULL DEFAULT now(),
	PRIMARY KEY (id),
	CONSTRAINT uq_agent_run_events_run_sequence UNIQUE (run_id, sequence),
	FOREIGN KEY(run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);
CREATE INDEX ix_agent_run_events_created_at ON agent_run_events (created_at);
CREATE INDEX ix_agent_run_events_run_id ON agent_run_events (run_id);
CREATE INDEX ix_agent_run_events_run_sequence ON agent_run_events (run_id, sequence);


CREATE TABLE chat_context_events (
	id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
	document_id BIGINT UNSIGNED NOT NULL,
	session_id BIGINT UNSIGNED NOT NULL,
	run_id VARCHAR(36),
	message_id BIGINT UNSIGNED,
	ordinal INTEGER NOT NULL,
	kind ENUM('USER','ASSISTANT','TOOL') NOT NULL,
	payload_json LONGTEXT NOT NULL,
	document_revision VARCHAR(128) NOT NULL,
	is_legacy BOOL NOT NULL,
	created_at DATETIME NOT NULL DEFAULT now(),
	PRIMARY KEY (id),
	CONSTRAINT uq_context_event_message_ordinal UNIQUE (session_id, message_id, ordinal),
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE,
	FOREIGN KEY(session_id) REFERENCES chat_sessions (id) ON DELETE CASCADE,
	FOREIGN KEY(run_id) REFERENCES agent_runs (id) ON DELETE SET NULL,
	FOREIGN KEY(message_id) REFERENCES chat_messages (id) ON DELETE SET NULL
);
CREATE INDEX ix_chat_context_events_document_id ON chat_context_events (document_id);
CREATE INDEX ix_chat_context_events_message_id ON chat_context_events (message_id);
CREATE INDEX ix_chat_context_events_run_id ON chat_context_events (run_id);
CREATE INDEX ix_chat_context_events_session_id ON chat_context_events (session_id);
CREATE INDEX ix_chat_context_events_session_id_id ON chat_context_events (session_id, id);


CREATE TABLE chat_tool_outputs (
	output_id VARCHAR(48) NOT NULL,
	document_id BIGINT UNSIGNED NOT NULL,
	session_id BIGINT UNSIGNED NOT NULL,
	run_id VARCHAR(36) NOT NULL,
	tool_call_id VARCHAR(160) NOT NULL,
	tool_name VARCHAR(160) NOT NULL,
	content LONGTEXT NOT NULL,
	content_bytes INTEGER NOT NULL,
	content_lines INTEGER NOT NULL,
	estimated_tokens INTEGER NOT NULL,
	checksum VARCHAR(64) NOT NULL,
	retention_mode VARCHAR(16) NOT NULL DEFAULT 'ttl',
	created_at DATETIME NOT NULL DEFAULT now(),
	expires_at DATETIME NOT NULL,
	PRIMARY KEY (output_id),
	CONSTRAINT uq_chat_tool_outputs_run_call UNIQUE (run_id, tool_call_id),
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE,
	FOREIGN KEY(session_id) REFERENCES chat_sessions (id) ON DELETE CASCADE,
	FOREIGN KEY(run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);
CREATE INDEX ix_chat_tool_outputs_document_id ON chat_tool_outputs (document_id);
CREATE INDEX ix_chat_tool_outputs_expires_at ON chat_tool_outputs (expires_at);
CREATE INDEX ix_chat_tool_outputs_run_id ON chat_tool_outputs (run_id);
CREATE INDEX ix_chat_tool_outputs_session_expires ON chat_tool_outputs (session_id, expires_at);
CREATE INDEX ix_chat_tool_outputs_session_id ON chat_tool_outputs (session_id);


CREATE TABLE chat_user_questions (
	id VARCHAR(36) NOT NULL,
	run_id VARCHAR(36) NOT NULL,
	document_id BIGINT UNSIGNED NOT NULL,
	session_id BIGINT UNSIGNED NOT NULL,
	user_id BIGINT UNSIGNED NOT NULL,
	model_id BIGINT UNSIGNED NOT NULL,
	tool_call_id VARCHAR(128) NOT NULL,
	status ENUM('WAITING','ANSWERED','CANCELLED') NOT NULL,
	question_json LONGTEXT NOT NULL,
	resume_messages_json LONGTEXT NOT NULL,
	completed_context_events_json LONGTEXT NOT NULL,
	execution_context_json LONGTEXT NOT NULL,
	timeline_json LONGTEXT NOT NULL,
	answer_json LONGTEXT NOT NULL,
	answer_client_request_id VARCHAR(96),
	last_activity_at DATETIME,
	timeout_at DATETIME,
	answered_at DATETIME,
	created_at DATETIME NOT NULL DEFAULT now(),
	PRIMARY KEY (id),
	CONSTRAINT uq_chat_user_questions_run_call UNIQUE (run_id, tool_call_id),
	CONSTRAINT uq_chat_user_questions_answer_request UNIQUE (answer_client_request_id),
	FOREIGN KEY(run_id) REFERENCES agent_runs (id) ON DELETE CASCADE,
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE,
	FOREIGN KEY(session_id) REFERENCES chat_sessions (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(model_id) REFERENCES ai_models (id) ON DELETE RESTRICT
);
CREATE INDEX ix_chat_user_questions_document_id ON chat_user_questions (document_id);
CREATE INDEX ix_chat_user_questions_run_id ON chat_user_questions (run_id);
CREATE INDEX ix_chat_user_questions_session_id ON chat_user_questions (session_id);
CREATE INDEX ix_chat_user_questions_timeout_at ON chat_user_questions (timeout_at);
CREATE INDEX ix_chat_user_questions_user_id ON chat_user_questions (user_id);

SET FOREIGN_KEY_CHECKS = 1;
